insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('ba34e1d3-435b-5f89-a092-b503ca76459e', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Vintage mid-century armchair, orange floral upholstery', '1960s lounge chair with walnut legs and the original orange-and-cream floral fabric. Frame is solid and doesn''t wobble; there''s light fading on the left arm and a small snag on the back. About 30" wide, 33" deep, 34" tall. Pillow not included. Pickup only, ground-floor brownstone near 7th Ave.', 180, 'home', 'good', 'active', '[{"fileId":"6aceef44ead997d09a5fa8e0","path":"/stoop/seed/orange-armchair-1.jpg","width":960,"height":640}]'::jsonb, 40.6725, -73.9875, 'Park Slope, Brooklyn', now() - interval '3435 minutes', now() - interval '3435 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('72a2cc92-30b1-5ed9-ba5b-f6ae9f502513', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Round black metal mirror with rope hanger, 20"', '20-inch round mirror with a thin matte black frame and jute rope strap. Hung on one wall for a year, no scratches on the glass. Swapping it for something bigger in the same spot. Cash or Venmo.', 45, 'home', 'like_new', 'active', '[{"fileId":"6aceef44ead997d09a5fa969","path":"/stoop/seed/round-strap-mirror-1.jpg","width":960,"height":1280}]'::jsonb, 40.6675, -73.985, 'Park Slope, Brooklyn', now() - interval '7266 minutes', now() - interval '7266 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('6a7bb20b-9dd0-5451-9630-37698a8bbd32', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Light blue upholstered loveseat, 52"', 'Compact two-seater in a pale aqua linen blend, 52" wide, wood legs. It fits through narrow brownstone doorways, which is why I bought it. Cushions are firm, no stains, one tiny pull on the front edge. Pillows and throw not included. Someone is coming Saturday; I''ll update if it falls through.', 220, 'home', 'good', 'reserved', '[{"fileId":"6aceef44ead997d09a5faa50","path":"/stoop/seed/blue-loveseat-1.jpg","width":960,"height":640}]'::jsonb, 40.675, -73.98, 'Park Slope, Brooklyn', now() - interval '12001 minutes', now() - interval '12001 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('6887ec62-e2bd-5792-be93-a5ef28778332', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Canon AE-1 film camera with 50mm f/1.8 lens', 'Canon AE-1 with the FD 50mm f/1.8. Fresh battery, meter reads accurately and the shutter doesn''t squeal. Light seals were replaced last year. Shot two rolls of Portra on it this summer with no issues. Neck strap included.', 240, 'hobbies', 'good', 'sold', '[{"fileId":"6aceef45ead997d09a5fab1d","path":"/stoop/seed/canon-ae1-1.jpg","width":960,"height":640}]'::jsonb, 40.675, -73.9875, 'Park Slope, Brooklyn', now() - interval '20493 minutes', now() - interval '20493 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('5ce271d5-fdda-59b4-a544-cce069f1919b', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Teal yoga mat with carry strap, 4mm', 'Standard 68" x 24" mat, 4mm thick, with an elastic carry strap. Used maybe ten times before I switched to a cork one. Wiped down and rolled. I can leave it with the doorman at my studio on Vanderbilt.', 15, 'sports', 'like_new', 'active', '[{"fileId":"6aceef45ead997d09a5fabde","path":"/stoop/seed/teal-yoga-mat-1.webp","width":1024,"height":683},{"fileId":"6aceef50ead997d09a5fc500","path":"/stoop/seed/teal-yoga-mat-2.webp","width":1024,"height":683},{"fileId":"6acf9d68ead997d09a627347","path":"/stoop/seed/teal-yoga-mat-d7cd67e7.webp","width":1024,"height":683}]'::jsonb, 40.6775, -73.975, 'Prospect Heights, Brooklyn', now() - interval '1921 minutes', now() - interval '1921 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('3bf10c7d-ee93-50cf-b56a-1e44a91f7a17', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'L.C. Smith & Corona portable typewriter, 1930s', 'Maroon Corona portable from the 1930s. All keys strike and the carriage advances, but the ribbon is dry and needs replacing. Some wear to the paint on the front edge, as you''d expect. Heavy, so pickup only. Great as a working piece or as decor.', 160, 'hobbies', 'fair', 'active', '[{"fileId":"6aceef51ead997d09a5fc8da","path":"/stoop/seed/corona-typewriter-1.jpg","width":960,"height":640},{"fileId":"6aceef51ead997d09a5fcaf8","path":"/stoop/seed/corona-typewriter-2.jpg","width":960,"height":640}]'::jsonb, 40.6675, -73.9825, 'Park Slope, Brooklyn', now() - interval '15869 minutes', now() - interval '15869 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('3a32b7e7-5ecb-58a0-9db5-3150af8b58b1', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'White rhinestone low-top sneakers, women''s 7.5', 'White canvas low-tops covered in small rhinestones, women''s US 7.5. Wore them once to a wedding reception. No missing stones that I can find, soles are clean. Satin laces included.', 30, 'fashion', 'like_new', 'active', '[{"fileId":"6aceef52ead997d09a5fcde1","path":"/stoop/seed/glitter-sneakers-1.jpg","width":960,"height":640}]'::jsonb, 40.665, -73.985, 'Park Slope, Brooklyn', now() - interval '6352 minutes', now() - interval '6352 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('fbfb81b3-7ef9-5cfb-a173-6e03eca406e9', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Free: two large empty picture frames', 'Two empty frames, no glass or backing. The wood one is about 30" x 40", the sage green one about 20" x 28". Good for a project or a gallery wall. On my stoop until they''re gone, first come first served.', 0, 'misc', null, 'active', '[{"fileId":"6aceef52ead997d09a5fd005","path":"/stoop/seed/free-picture-frames-1.jpg","width":960,"height":640}]'::jsonb, 40.6725, -73.98, 'Park Slope, Brooklyn', now() - interval '103 minutes', now() - interval '103 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('9f941c50-5324-5d60-853b-8d3424e80a30', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Black steel road bike, converted single speed, 56cm', 'Vintage steel frame, 56cm, converted to single speed with a new chain and freewheel this spring. Drop bars, sprung leather saddle, both brakes work. Fits riders about 5''9" to 6''0". Tires hold air fine. Test ride welcome if you leave ID.', 260, 'sports', 'good', 'active', '[{"fileId":"6aceef52ead997d09a5fd0ae","path":"/stoop/seed/black-single-speed-1.jpg","width":960,"height":640}]'::jsonb, 40.685, -73.94, 'Bed-Stuy, Brooklyn', now() - interval '4386 minutes', now() - interval '4386 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('985ff96c-7f7c-5980-84fd-cbc27f2563e1', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Spin-lock dumbbell set with 6 extra cast iron plates', 'Pair of chrome spin-lock handles plus cast iron plates, about 40 lb total. Threads are clean and the collars tighten fine. Some surface rust on a couple of plates. Third floor walk-up, I''ll bring them down.', 55, 'sports', 'good', 'active', '[{"fileId":"6aceef52ead997d09a5fd144","path":"/stoop/seed/dumbbell-set-1.webp","width":1024,"height":683}]'::jsonb, 40.69, -73.9475, 'Bed-Stuy, Brooklyn', now() - interval '13404 minutes', now() - interval '13404 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('c1135117-02f7-5f7c-a597-4f655e51fe05', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Technics SL-1200MK5 turntable with Ortofon cartridge', 'SL-1200MK5 in silver, Ortofon cartridge on the headshell. Pitch slider and start/stop work as they should, speed is locked on both 33 and 45. Dust cover has scratches, deck itself is clean. Selling because I went digital for gigs. Pending pickup, will relist if it doesn''t happen.', 650, 'electronics', 'good', 'reserved', '[{"fileId":"6aceef54ead997d09a5fd575","path":"/stoop/seed/technics-turntable-1.webp","width":1024,"height":788}]'::jsonb, 40.69, -73.94, 'Bed-Stuy, Brooklyn', now() - interval '8706 minutes', now() - interval '8706 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('8799741f-2533-57c2-ad24-53a909f00a55', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Lot of about 40 classical and pop LPs', 'Box of roughly 40 records, mostly classical pressings from the 70s plus a Beatles compilation. Sleeves are worn and some have ring wear, but the vinyl I spot-checked plays fine. Selling as a lot only.', 80, 'hobbies', 'fair', 'sold', '[{"fileId":"6aceef55ead997d09a5fd7b9","path":"/stoop/seed/vinyl-lot-1.webp","width":1024,"height":564}]'::jsonb, 40.685, -73.945, 'Bed-Stuy, Brooklyn', now() - interval '30573 minutes', now() - interval '30573 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('b44e7362-6600-519b-ba15-bf8f3e859d8a', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Brown leather messenger bag, fits 13" laptop', 'Full-grain brown leather messenger with two buckle straps and a padded shoulder pad. Fits a 13-inch laptop plus a camera. Leather is scuffed in the way it should be, all stitching intact. I''m at my studio in Fort Greene most afternoons.', 95, 'fashion', 'good', 'active', '[{"fileId":"6aceef56ead997d09a5fd83c","path":"/stoop/seed/leather-messenger-1.jpg","width":960,"height":572}]'::jsonb, 40.695, -73.975, 'Fort Greene, Brooklyn', now() - interval '17309 minutes', now() - interval '17309 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('7fbf9618-b381-50e0-99d6-177cbeca5a66', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'MacBook Pro 13" Retina, 16GB RAM, 512GB SSD', '13-inch MacBook Pro, silver, 16GB RAM and 512GB SSD. Battery cycle count is 312 and health shows normal. Wiped and reset, signed out of iCloud. Small dent on the bottom corner, screen is perfect. Comes with the original charger. Can meet at the Astoria Blvd station.', 420, 'electronics', 'good', 'active', '[{"fileId":"6aceef56ead997d09a5fd8cb","path":"/stoop/seed/macbook-pro-13-1.jpg","width":960,"height":638}]'::jsonb, 40.76, -73.9275, 'Astoria, Queens', now() - interval '3398 minutes', now() - interval '3398 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('4a02484b-199d-5190-ae31-94c5b6449561', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Logitech MX Keys wireless keyboard, graphite', 'MX Keys in graphite, US layout. Backlight works, pairs with three devices. I moved to a mechanical board so this has been in a drawer. USB-C cable included.', 55, 'electronics', 'like_new', 'active', '[{"fileId":"6aceef56ead997d09a5fd950","path":"/stoop/seed/mx-keys-1.jpg","width":960,"height":720}]'::jsonb, 40.7675, -73.9225, 'Astoria, Queens', now() - interval '6019 minutes', now() - interval '6019 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('b51a5801-6213-54a4-b43a-4566043877c1', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Apple iMac 21.5", 8GB RAM, keyboard and mouse included', '21.5-inch iMac, 8GB RAM, 1TB drive. Freshly reset to macOS. Comes with the wired keyboard and Magic Mouse. Screen has no dead pixels. It''s at my office in LIC, so pickup there on weekdays. Heavy-ish, bring a bag.', 300, 'electronics', 'good', 'active', '[{"fileId":"6aceef56ead997d09a5fd9f9","path":"/stoop/seed/imac-21-1.jpg","width":960,"height":640},{"fileId":"6acf9d6aead997d09a62795a","path":"/stoop/seed/imac-21-b2cbaa0f.jpg","width":960,"height":640},{"fileId":"6acf9d6aead997d09a627a75","path":"/stoop/seed/imac-21-a4e4cecf.jpg","width":960,"height":640}]'::jsonb, 40.7475, -73.945, 'Long Island City, Queens', now() - interval '14659 minutes', now() - interval '14659 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('742c027e-4345-52a0-81e7-85f00a85c6f6', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'IKEA Hektar floor lamp, dark grey', 'Hektar floor lamp, adjustable shade, about 69" tall. Works fine, a few small scuffs on the base. Bulb included. Pickup only, 2nd floor walk-up off 30th Ave.', 25, 'home', 'good', 'active', '[{"fileId":"6aceef57ead997d09a5fda84","path":"/stoop/seed/floor-lamp-1.webp","width":1024,"height":686}]'::jsonb, 40.765, -73.9175, 'Astoria, Queens', now() - interval '10450 minutes', now() - interval '10450 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('2b0f8cee-7c31-525a-9a59-1b0708697e06', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Beige carpeted cat condo with scratching posts', 'Two-post cat tree with a covered cubby, about 3 feet tall. Sisal on the posts is worn from use, carpet has been vacuumed. Our cat prefers the couch, so it''s going. Fits in a hatchback.', 35, 'pets', 'fair', 'active', '[{"fileId":"6aceef57ead997d09a5fdb5a","path":"/stoop/seed/cat-condo-1.webp","width":1024,"height":769}]'::jsonb, 40.7625, -73.9225, 'Astoria, Queens', now() - interval '21933 minutes', now() - interval '21933 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('4dbc8a99-5f0b-589f-aee3-da2c70486dcd', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Adult tennis racket, grip 2, with a new ball', 'Adult racket, grip size 2, strung last season. Some paint chips on the frame from scraping serves. I''ll throw in a fresh ball. I can meet at Astoria Park courts.', 40, 'sports', 'good', 'active', '[{"fileId":"6aceef58ead997d09a5fde51","path":"/stoop/seed/tennis-racket-1.webp","width":1024,"height":684},{"fileId":"6acf9d6aead997d09a627bf4","path":"/stoop/seed/tennis-racket-82e726fe.webp","width":1024,"height":683}]'::jsonb, 40.7675, -73.9225, 'Astoria, Queens', now() - interval '26401 minutes', now() - interval '26401 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
