insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('2032f6bb-80eb-5f32-bf62-1b27866d423e', '8221bed2-7e99-5ae8-864d-53a62aa7dcad', 'Wooden cruiser skateboard, 36", red wheels', 'Oak-veneer cruiser, about 36 inches, soft red wheels that eat up rough pavement. Bearings spin fine, trucks are a bit loose but adjustable. Headphones not included. Can meet near Maria Hernandez Park.', 70, 'sports', 'good', 'active', '[{"fileId":"6aceef59ead997d09a5fe024","path":"/stoop/seed/cruiser-skateboard-1.jpg","width":960,"height":640}]'::jsonb, 40.6975, -73.9275, 'Bushwick, Brooklyn', now() - interval '7266 minutes', now() - interval '7266 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
