insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('2039dc30-7624-56b5-9c1f-99acc747a725', '8221bed2-7e99-5ae8-864d-53a62aa7dcad', 'Free: flattened moving boxes, about 25', 'About 25 flattened cardboard boxes in mixed sizes, tied in bundles. Some have tape residue but all are usable. Take them all, please. Leaving them by my building door tonight, or message me and I''ll hold them.', 0, 'misc', null, 'active', '[{"fileId":"6aceef5cead997d09a5fe5ca","path":"/stoop/seed/free-boxes-1.webp","width":1024,"height":768}]'::jsonb, 40.69, -73.925, 'Bushwick, Brooklyn', now() - interval '370 minutes', now() - interval '370 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('8048c46f-f0eb-5fb6-8ccc-5134929bafb8', '33f1a5e1-6e59-56f3-a505-ad73d1d3f1f1', 'Ornate gilt wall mirror, antique, 22"', 'Heavy cast metal mirror with gilt finish, figures and a lion mask at the bottom. Roughly 22 inches tall. The mirror glass itself has the foxing and silvering loss you see in old pieces. It hung in my hallway for decades. Doorman building on West End Ave, I can have it waiting downstairs.', 280, 'home', 'fair', 'active', '[{"fileId":"6aceef5cead997d09a5fe69b","path":"/stoop/seed/gold-wall-mirror-1.jpg","width":960,"height":1439}]'::jsonb, 40.7875, -73.9775, 'Upper West Side, Manhattan', now() - interval '9232 minutes', now() - interval '9232 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
