insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('2be9c1d4-be73-5fbc-9b7f-c4213fa93057', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Large black cubby bookcase, 6 x 8 grid', 'Big painted black bookcase, about 9 feet wide and 7 feet tall, 48 cubbies. It comes apart into three sections. Some chipped paint on the edges. You''ll need a van and a friend. Books and objects not included.', 150, 'home', 'fair', 'active', '[{"fileId":"6aceef61ead997d09a5ff436","path":"/stoop/seed/cube-bookcase-1.jpg","width":960,"height":636}]'::jsonb, 40.7325, -73.9525, 'Greenpoint, Brooklyn', now() - interval '13441 minutes', now() - interval '13441 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('04116b74-3e7a-599e-9632-3d011feb019c', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Acoustic parlor guitar, natural finish', 'Small-bodied acoustic, great for couch playing or travel. Plays in tune, action is a bit high. Some wear on the top and a few dings on the edges. I''ll leave the strings on. Stored at my friend''s place near McCarren Park.', 85, 'hobbies', 'fair', 'active', '[{"fileId":"6aceef61ead997d09a5ff770","path":"/stoop/seed/parlor-guitar-1.jpg","width":960,"height":1280}]'::jsonb, 40.7125, -73.9575, 'Williamsburg, Brooklyn', now() - interval '10561 minutes', now() - interval '10561 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('bbc06cd9-cf61-5734-ac75-a9bc77b951fa', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Marshall Major II wired headphones, black', 'Marshall Major II on-ear headphones with the coiled cable. Sound is great, pads are a bit worn but not peeling. The headband folds. Can meet at the Nassau Ave G stop.', 40, 'electronics', 'good', 'active', '[{"fileId":"6aceef61ead997d09a5ffa36","path":"/stoop/seed/marshall-headphones-1.webp","width":1024,"height":683}]'::jsonb, 40.7275, -73.955, 'Greenpoint, Brooklyn', now() - interval '17383 minutes', now() - interval '17383 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('05553761-5d26-582b-baa0-3e170efa4c09', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Round white tulip table with two bentwood chairs', 'White pedestal table, 32" round, seats two comfortably or three if you''re friendly. The two chairs have molded plywood frames and black faux-leather seats and backs. Small ring mark on the tabletop that you only see in raking light. Plants and book not included. Pending pickup Sunday, I''ll update if it falls through.', 260, 'home', 'good', 'reserved', '[{"fileId":"6acf7bcbead997d09a9d6771","path":"/stoop/seed/tulip-table-set-1.jpg","width":960,"height":640}]'::jsonb, 40.6725, -73.98, 'Park Slope, Brooklyn', now() - interval '4875 minutes', now() - interval '4875 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('63aec3d5-cc61-5441-9f5d-447e1e8588f2', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Grey tufted three-seat sofa, 84"', 'Light grey linen-look sofa with a button-tufted back and dark wood legs, 84" wide, 34" deep. Very comfortable, no stains, cushions still hold their shape. Pillows and the coffee table stayed with me. Sold to a lovely couple from Windsor Terrace, thanks everyone.', 450, 'home', 'good', 'sold', '[{"fileId":"6acf7bcbead997d09a9d683a","path":"/stoop/seed/grey-tufted-sofa-1.jpg","width":960,"height":640}]'::jsonb, 40.67, -73.9825, 'Park Slope, Brooklyn', now() - interval '27952 minutes', now() - interval '27952 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('ac8e67ea-2859-5c46-8af4-0116add96d50', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Black metal desk lamp with brass details, adjustable arm', 'Matte black task lamp with a brass collar and a counterweighted arm that swings and tilts. Round weighted base, about 20" tall. Takes a regular E26 bulb (warm LED included). Used for a client staging and then went back in the box. Succulent not included.', 35, 'home', 'like_new', 'active', '[{"fileId":"6acf7bcbead997d09a9d6963","path":"/stoop/seed/black-desk-lamp-1.jpg","width":960,"height":1222}]'::jsonb, 40.6775, -73.9675, 'Prospect Heights, Brooklyn', now() - interval '3435 minutes', now() - interval '3435 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('8971ffc2-ca29-5a6c-9ba5-d78c162317cb', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Big spider plant in a teal ceramic pot with saucer', 'Healthy spider plant, about 18" across, in a glossy teal ceramic pot (6" diameter) with a matching saucer. It''s thrown off two babies already, which I''m happy to include in a jar. Easy plant, likes bright indirect light. Books not included. Pickup near Smith St.', 20, 'home', 'good', 'active', '[{"fileId":"6acf7bccead997d09a9d6b26","path":"/stoop/seed/spider-plant-1.jpg","width":960,"height":640}]'::jsonb, 40.68, -73.9975, 'Carroll Gardens, Brooklyn', now() - interval '444 minutes', now() - interval '444 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('e6ce5dbf-6369-520d-b906-b81293c89785', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Black floral crossbody bag with chain strap', 'Small structured crossbody in black with a pink and green floral print, gold push-lock clasp and a chain shoulder strap. Fits a phone, cards and keys, not much else. Carried it to two weddings. Sunglasses not included.', 40, 'fashion', 'like_new', 'active', '[{"fileId":"6acf7bccead997d09a9d6c7b","path":"/stoop/seed/floral-crossbody-1.jpg","width":960,"height":1440},{"fileId":"6acf9d6cead997d09a628464","path":"/stoop/seed/floral-crossbody-8e1549b6.jpg","width":960,"height":1440}]'::jsonb, 40.675, -73.9775, 'Park Slope, Brooklyn', now() - interval '9232 minutes', now() - interval '9232 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('3a105f9d-b383-595f-8fce-ce233894edbe', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', '1974 Volkswagen Thing, orange, convertible', '1974 VW Type 181 "Thing" in its original orange, with whitewalls and painted red wheels. Fold-down windshield, removable doors, new soft top in the trunk. 1600cc air-cooled engine rebuilt in 2021, about 4,000 miles since. Floors are solid, some patina on the rear quarters. NY title in my name. Garaged in Gowanus. A buyer is coming with a mechanic on Thursday, will update.', 14500, 'vehicles', 'good', 'reserved', '[{"fileId":"6acf7bccead997d09a9d6dbe","path":"/stoop/seed/vw-thing-1.jpg","width":960,"height":637}]'::jsonb, 40.675, -73.99, 'Gowanus, Brooklyn', now() - interval '14696 minutes', now() - interval '14696 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('3bb6c283-4451-5729-8d5e-e6d67da22b63', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Three plush Scandinavian holiday gnomes', 'Set of three fabric gnomes, about 14" tall: one with a red polka-dot hat, one in a cream knit hat with a brown beard, one in a red and white woven hat. Bought them for a holiday window display and they''re too cute to throw away. Sold as a set. Getting a head start before December.', 25, 'misc', 'like_new', 'active', '[{"fileId":"6acf7bcdead997d09a9d6f9b","path":"/stoop/seed/holiday-gnomes-1.jpg","width":960,"height":1440},{"fileId":"6acf9d6cead997d09a628f15","path":"/stoop/seed/holiday-gnomes-d2e9480f.jpg","width":960,"height":1399}]'::jsonb, 40.6725, -73.9775, 'Park Slope, Brooklyn', now() - interval '1958 minutes', now() - interval '1958 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('0707578c-2f29-5a88-82b5-d8cdacf8cd46', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Black integrated stereo amplifier with phono input', 'Black 90s integrated amp with the "Super Stable" circuit. Built-in phono stage, so you can plug a turntable straight in. Inputs for CD, tuner, aux and tape, plus loudness and source direct. Both channels clean, no scratchy pots. Some wear on the top panel. Speakers not included. Come hear it before you buy.', 140, 'electronics', 'good', 'active', '[{"fileId":"6acf7bcdead997d09a9d7130","path":"/stoop/seed/stereo-amp-1.jpg","width":960,"height":1440}]'::jsonb, 40.6875, -73.9425, 'Bed-Stuy, Brooklyn', now() - interval '6130 minutes', now() - interval '6130 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('97ed8be5-3ceb-538c-ac9a-d3dd1101ac24', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Pair of white cube desktop speakers', 'Small white cube speakers, about 4" each, on angled stands with silver trim. Powered over USB with a 3.5mm input. Surprisingly decent for a desk or a kitchen counter. Have the original box. Someone''s picking them up after work.', 30, 'electronics', 'like_new', 'reserved', '[{"fileId":"6acf7bcdead997d09a9d720a","path":"/stoop/seed/white-cube-speakers-1.jpg","width":960,"height":1440}]'::jsonb, 40.685, -73.9375, 'Bed-Stuy, Brooklyn', now() - interval '11623 minutes', now() - interval '11623 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('97e8644d-21b2-52ee-bcc2-48a9819b4b2d', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Vintage light blue steel road bike, 54cm, 10-speed', '70s steel road bike in pale blue with downtube shifters, drop bars wrapped in blue tape and a black saddle. 54cm frame, fits riders about 5''6" to 5''10". New cables and brake pads last month, shifts cleanly. Paint has a few chips. Test ride welcome with ID.', 240, 'sports', 'good', 'active', '[{"fileId":"6acf7bcdead997d09a9d7349","path":"/stoop/seed/blue-road-bike-1.jpg","width":960,"height":640}]'::jsonb, 40.69, -73.9475, 'Bed-Stuy, Brooklyn', now() - interval '3398 minutes', now() - interval '3398 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('b9c86035-df93-5cbe-81a3-ac69b9d1ec69', '499a659a-d8f7-5f18-b366-9e13d33860e0', '2016 Harley-Davidson Sportster Forty-Eight, 9,400 miles', 'Black 2016 Forty-Eight, 1200cc, 9,400 miles. Fat front tire, solo seat with a removable passenger pad and backrest. Serviced in August, new battery. Never dropped. Clean NY title in hand. Parked in Clinton Hill, serious buyers only please.', 7800, 'vehicles', 'good', 'active', '[{"fileId":"6acf7bceead997d09a9d745a","path":"/stoop/seed/sportster-48-1.jpg","width":960,"height":640}]'::jsonb, 40.69, -73.965, 'Clinton Hill, Brooklyn', now() - interval '7644 minutes', now() - interval '7644 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('bd23cfc1-572f-5cd4-ab9b-feec4f379d24', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Two pairs of leather boxing gloves, 14 oz and 16 oz', 'One blue and white pair (16 oz) and one red pair (14 oz), both real leather with velcro wrist straps. Broken in but no splits in the padding, and they''ve been aired out and wiped down. Good for bag work or a partner who wants to start. Selling both together.', 45, 'sports', 'good', 'active', '[{"fileId":"6acf7bceead997d09a9d7567","path":"/stoop/seed/boxing-gloves-1.webp","width":1024,"height":682}]'::jsonb, 40.6825, -73.9325, 'Bed-Stuy, Brooklyn', now() - interval '17761 minutes', now() - interval '17761 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('8559933f-659d-5a2d-a460-e4d2c68b3ecf', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Bright 1BR with open kitchen, Bed-Stuy — $2,550/mo', 'Lease takeover for my cousin''s one-bedroom, she''s moving to Atlanta. Big open living room and kitchen, oak floors, tall windows, and a separate bedroom behind sliding doors that fits a queen. Third floor of a brownstone, 6 minutes to the Utica Ave A/C. Available Dec 1, lease runs through next August with the option to renew. The desk and chairs can stay if you want them. No broker fee.', 2550, 'property', null, 'active', '[{"fileId":"6acf9d6cead997d09a629973","path":"/stoop/seed/bed-stuy-1br-8a2b71b8.jpg","width":1280,"height":960},{"fileId":"6acf9d6dead997d09a629bb2","path":"/stoop/seed/bed-stuy-1br-01ad6909.jpg","width":1280,"height":960},{"fileId":"6acf9d6dead997d09a629dc6","path":"/stoop/seed/bed-stuy-1br-2a75cabb.jpg","width":1280,"height":960},{"fileId":"6acf9d6dead997d09a629f47","path":"/stoop/seed/bed-stuy-1br-2c4c75d4.jpg","width":1280,"height":960}]'::jsonb, 40.6875, -73.935, 'Bed-Stuy, Brooklyn', now() - interval '4764 minutes', now() - interval '4764 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('436ce093-9557-51cb-bea0-6d4fdf76bb04', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'White Casio G-Shock GA-100, navy dial', 'G-Shock GA-100 in white with the navy and blue dial. Keeps perfect time, light and alarm work, new battery in the spring. Strap is clean, a few marks on the bezel. Don''t wear it anymore since I got a smartwatch.', 55, 'fashion', 'good', 'active', '[{"fileId":"6acf7bceead997d09a9d7846","path":"/stoop/seed/white-gshock-1.jpg","width":960,"height":638}]'::jsonb, 40.6875, -73.94, 'Bed-Stuy, Brooklyn', now() - interval '22044 minutes', now() - interval '22044 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('4a79946c-7686-5492-854c-232761b9f808', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Hollow-body archtop electric guitar, dark sunburst', 'Full hollow-body archtop with a single cutaway, dark brown sunburst, two humbuckers, gold hardware and a trapeze tailpiece. Plays great for jazz and blues, warm neck pickup. Some buckle rash on the back. Gig bag included. Sold, thanks for all the messages.', 320, 'hobbies', 'good', 'sold', '[{"fileId":"6acf7bcfead997d09a9d7906","path":"/stoop/seed/hollowbody-guitar-1.jpg","width":960,"height":640}]'::jsonb, 40.69, -73.975, 'Fort Greene, Brooklyn', now() - interval '31709 minutes', now() - interval '31709 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('95c011e8-a16c-5071-aacf-4326cdabd9b9', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Khaki hooded dog parka, size L', 'Khaki water-resistant dog coat with a hood and fleece lining, size L (chest about 26", back length 20"). That''s our pit mix Juno in it, about 45 lb. She got a new one from her grandma, so this one''s up for grabs. Washed and ready.', 20, 'pets', 'like_new', 'active', '[{"fileId":"6acf7bcfead997d09a9d79c2","path":"/stoop/seed/dog-parka-1.jpg","width":960,"height":640},{"fileId":"6acf9d6dead997d09a62a01f","path":"/stoop/seed/dog-parka-bc265919.jpg","width":960,"height":640}]'::jsonb, 40.6875, -73.945, 'Bed-Stuy, Brooklyn', now() - interval '10413 minutes', now() - interval '10413 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('497a7480-e442-5715-8f0e-1199c2e4736a', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Two Android phones, Nexus 5 and Nexus 4, unlocked', 'Two old Google phones, both factory reset and unlocked. The Nexus 5 (16GB) has a good screen and a tired battery that lasts about half a day. The Nexus 4 has a small crack on the back glass, screen is fine. Good as a backup phone, a kid''s first phone, or for tinkering with custom ROMs. One USB cable included. Sold together.', 60, 'electronics', 'fair', 'active', '[{"fileId":"6acf7bcfead997d09a9d7abe","path":"/stoop/seed/nexus-phones-1.jpg","width":960,"height":640}]'::jsonb, 40.765, -73.9225, 'Astoria, Queens', now() - interval '13404 minutes', now() - interval '13404 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('7efe6aa3-53bb-5030-8dd0-375e516eebc3', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Apple Watch Series 3, 42mm space grey, black sport band', 'Series 3 GPS, 42mm space grey aluminum with the black sport band. Battery health 86%. Unpaired and reset, ready for a new iPhone. Light scuffs on the case edge, screen has no scratches. Magnetic charger included. Can meet at the 30th Ave stop.', 90, 'electronics', 'good', 'active', '[{"fileId":"6acf7bcfead997d09a9d7be3","path":"/stoop/seed/apple-watch-1.jpg","width":960,"height":640}]'::jsonb, 40.7625, -73.9275, 'Astoria, Queens', now() - interval '1847 minutes', now() - interval '1847 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('9e2cb291-f33f-5fa6-a71f-8afa290c6952', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Furnished room in 2BR, Astoria — $1,400/mo', 'Big bright room in a 2BR near Ditmars, available Nov 15. Comes furnished with a queen bed with storage drawers, two nightstands and lamps, or I can clear it out. You''d share the apartment with me (software engineer, quiet, out at the office three days a week) and my cat. Open kitchen with an island and a dishwasher, and a living room with a big sofa. Closet, laundry in the building. Utilities around $70. Looking for someone for at least 6 months.', 1400, 'property', null, 'active', '[{"fileId":"6acf9d6eead997d09a62a1a4","path":"/stoop/seed/astoria-room-e5a19abc.jpg","width":1024,"height":683},{"fileId":"6acf9d6eead997d09a62a24b","path":"/stoop/seed/astoria-room-bce39bce.jpg","width":1024,"height":683},{"fileId":"6acf9d6eead997d09a62a2f9","path":"/stoop/seed/astoria-room-9b03971a.jpg","width":1024,"height":683},{"fileId":"6acf9d6fead997d09a62a451","path":"/stoop/seed/astoria-room-f48605a5.jpg","width":1024,"height":683}]'::jsonb, 40.77, -73.915, 'Astoria, Queens', now() - interval '444 minutes', now() - interval '444 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('21ed1b79-fa58-527e-9c55-122f21c3e902', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Cat cave bed, coral and lime green', 'Soft fabric cat cave, coral outside with a lime green rim, about 16" tall. Our cat napped in it for exactly one week and then went back to my laptop bag. Machine washable cover, just washed. The cat in the photo is not included, sadly.', 15, 'pets', 'good', 'active', '[{"fileId":"6acf7bd0ead997d09a9d7ec9","path":"/stoop/seed/cat-cave-bed-1.jpg","width":1024,"height":768}]'::jsonb, 40.7625, -73.92, 'Astoria, Queens', now() - interval '9084 minutes', now() - interval '9084 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('7034ea80-9fae-5da3-be8f-99e5e19983bd', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Parking spot in secure garage, LIC — $300/mo', 'Indoor parking spot in my building''s garage off Jackson Ave, roll-up door with keypad entry. Fits a sedan or small SUV, not a full-size pickup. Available month to month starting now since I sold my car. Five minutes to the Court Sq station. Venmo or check on the 1st.', 300, 'property', null, 'active', '[{"fileId":"6acf7bd0ead997d09a9d7fbe","path":"/stoop/seed/lic-parking-spot-1.jpg","width":960,"height":640}]'::jsonb, 40.745, -73.9475, 'Long Island City, Queens', now() - interval '6352 minutes', now() - interval '6352 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('253af94e-c2c7-57a9-8669-eef552a7544c', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Wooden backgammon set in folding case', 'Full-size wooden backgammon board, natural and black inlay, folds into a case with metal latches. All 30 checkers and both dice are there. Played a handful of times at my parents'' place. Pickup in Jackson Heights on weekends or Astoria on weekdays.', 45, 'hobbies', 'like_new', 'active', '[{"fileId":"6acf7bd0ead997d09a9d81c2","path":"/stoop/seed/backgammon-set-1.jpg","width":960,"height":641}]'::jsonb, 40.755, -73.8825, 'Jackson Heights, Queens', now() - interval '16358 minutes', now() - interval '16358 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('451c4ef1-8bbf-59e0-b8e9-0b76b4879f08', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Triumph Thruxton 900 cafe racer, white, 11k miles', '2014 Thruxton 900 in white, about 11,000 miles. Brown tuck-and-roll seat, clip-on bars, spoked wheels. Fuel injected, starts easily even in the cold. New rear tire last season, chain and sprockets in good shape. I commuted on it to LIC but it''s mostly been parked since I went remote. On hold for a buyer coming Saturday.', 6200, 'vehicles', 'good', 'reserved', '[{"fileId":"6acf7bd1ead997d09a9d829d","path":"/stoop/seed/thruxton-cafe-1.jpg","width":960,"height":640}]'::jsonb, 40.7475, -73.9425, 'Long Island City, Queens', now() - interval '10561 minutes', now() - interval '10561 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('b2e5e78d-9a76-5de6-8098-7889d9b43b74', '8221bed2-7e99-5ae8-864d-53a62aa7dcad', 'Free: red upholstered armchair', 'Boxy armchair in red wool fabric with light wood legs. Comfortable and sturdy, fabric is a little pilled on the arms. No pets, no smoking, no bugs. It''s out front of my building off Troutman right now, come grab it before the sanitation truck does.', 0, 'home', 'fair', 'active', '[{"fileId":"6acf7bd1ead997d09a9d833d","path":"/stoop/seed/free-red-armchair-1.jpg","width":960,"height":540}]'::jsonb, 40.695, -73.92, 'Bushwick, Brooklyn', now() - interval '29 minutes', now() - interval '29 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('73fa370c-96bb-5979-a431-3806660d7a33', '8221bed2-7e99-5ae8-864d-53a62aa7dcad', 'Peugeot Looxor 50cc scooter, black', 'Black Peugeot Looxor 50, two-stroke, around 9,000 km. Starts on the button once it''s warm, kick start always works. Seat is clean, mirrors and lights all work, a few scratches on the side panels. Good for short city runs. Has the title, no plates. Selling because I''m moving at the end of the month.', 900, 'vehicles', 'fair', 'active', '[{"fileId":"6acf7bd1ead997d09a9d8489","path":"/stoop/seed/looxor-scooter-1.jpg","width":1024,"height":683}]'::jsonb, 40.7, -73.925, 'Bushwick, Brooklyn', now() - interval '4838 minutes', now() - interval '4838 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('c838ecb4-41fe-5af0-bcfc-788390a8c67e', '8221bed2-7e99-5ae8-864d-53a62aa7dcad', 'Two surfboards: 9''0" longboard and 7''6" funboard', 'White 9''0" single-fin longboard and a navy 7''6" funboard. Both water-tight, a couple of professional ding repairs on the longboard rail. Good for Rockaway. $380 for both or $220 / $180 separately. Fins included. You need a car or a very patient bus driver.', 380, 'sports', 'good', 'active', '[{"fileId":"6acf7bd1ead997d09a9d8527","path":"/stoop/seed/surfboards-1.jpg","width":960,"height":640}]'::jsonb, 40.6975, -73.9225, 'Bushwick, Brooklyn', now() - interval '19090 minutes', now() - interval '19090 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('e41202c5-c901-5e81-9a17-9ee9b22a4f39', '8221bed2-7e99-5ae8-864d-53a62aa7dcad', 'Metric socket set with 1/4" ratchet, in case', '1/4" drive set with chrome sockets from 4 to 14mm, bit sockets, extension and a quick-release ratchet, all in a black hard case. Nothing missing that I know of. Used it to keep my scooter going. Moving and trying to lighten the load.', 30, 'misc', 'good', 'active', '[{"fileId":"6acf7bd2ead997d09a9d85c0","path":"/stoop/seed/socket-set-1.jpg","width":960,"height":640}]'::jsonb, 40.6925, -73.9175, 'Bushwick, Brooklyn', now() - interval '7570 minutes', now() - interval '7570 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('1afb537f-7b05-54ba-b6c8-9e3c36e9154d', '8221bed2-7e99-5ae8-864d-53a62aa7dcad', '10-gallon aquarium kit with hood, filter and decor', 'Standard 10-gallon glass tank (20" x 10" x 12") with a black hood, light and hang-on filter. Comes with the gravel, rock, driftwood and fake plants. Doesn''t leak. The goldfish found a new home with my neighbor''s kid. Pickup only, near the Seneca Ave M.', 35, 'pets', 'good', 'active', '[{"fileId":"6acf7bd2ead997d09a9d871e","path":"/stoop/seed/fish-tank-10gal-1.jpg","width":1024,"height":718}]'::jsonb, 40.705, -73.905, 'Ridgewood, Queens', now() - interval '12075 minutes', now() - interval '12075 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('ed3e251d-c0f2-5d3b-ae72-68edbddc5015', '8221bed2-7e99-5ae8-864d-53a62aa7dcad', 'Lot of 20+ vintage LEGO minifigures, 70s and 80s', 'Classic minifigs from my childhood: red and white Space astronauts, castle knights with helmets, town figures, plus the printed Legoland Snack Bar and Police bricks and a few printed slopes. Some play wear on the prints, no cracked torsos. Sold to a collector in Ridgewood.', 110, 'hobbies', 'good', 'sold', '[{"fileId":"6acf7bd2ead997d09a9d8973","path":"/stoop/seed/vintage-lego-minifigs-1.jpg","width":1023,"height":682}]'::jsonb, 40.6925, -73.925, 'Bushwick, Brooklyn', now() - interval '36177 minutes', now() - interval '36177 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('32589e27-d8c9-582f-9457-f378d131c3d7', '33f1a5e1-6e59-56f3-a505-ad73d1d3f1f1', 'Stack of eight antique cloth hardcovers', 'Eight old cloth-bound books, early 1900s to 1940s, including In Tune with the Infinite, The Transforming Friendship and an anthology of English poems. Spines are faded and a couple of the top ones are fraying, pages intact. Lovely on a shelf or a coffee table. Selling as a lot.', 30, 'hobbies', 'fair', 'active', '[{"fileId":"6acf7bd3ead997d09a9d8d74","path":"/stoop/seed/vintage-hardcovers-1.jpg","width":960,"height":611}]'::jsonb, 40.7875, -73.975, 'Upper West Side, Manhattan', now() - interval '13026 minutes', now() - interval '13026 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('96ecaf15-425b-5bc4-a9b1-e0ed0344468a', '33f1a5e1-6e59-56f3-a505-ad73d1d3f1f1', 'Three vintage suitcases, stackable', 'Tan leather case on top, a striped red, blue and yellow "Cabin" case in the middle and a big brown one at the bottom. All latches open and close, the brown one has a key. Scuffs, travel stickers and character. They''ve been in my sister''s hall closet in Harlem for years, pickup there. Great as side-table storage.', 90, 'misc', 'fair', 'active', '[{"fileId":"6acf7bd3ead997d09a9d8fab","path":"/stoop/seed/vintage-suitcases-1.jpg","width":960,"height":540}]'::jsonb, 40.81, -73.945, 'Harlem, Manhattan', now() - interval '5789 minutes', now() - interval '5789 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('e247eb00-34d4-5c41-a8e7-c580c10791c0', '33f1a5e1-6e59-56f3-a505-ad73d1d3f1f1', 'Mohair teddy bear in a hand-knit blue sweater', 'Golden mohair teddy, about 12" tall, jointed arms and legs, wearing a blue sweater I knitted for him. Stitched eyes and nose, so safe for little ones. Clean and stored in a smoke-free home. Looking for a grandchild who''ll actually play with him.', 25, 'kids', 'good', 'active', '[{"fileId":"6acf7bd3ead997d09a9d916d","path":"/stoop/seed/mohair-teddy-1.jpg","width":960,"height":620}]'::jsonb, 40.7825, -73.9775, 'Upper West Side, Manhattan', now() - interval '20604 minutes', now() - interval '20604 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('01862281-189b-53c4-aebe-d7a598674ba9', '33f1a5e1-6e59-56f3-a505-ad73d1d3f1f1', 'Bundle of 12 summer dresses, women''s S–M', 'Twelve dresses my daughter left behind when she moved to Portland: florals, a mint green slip dress, a teal maxi, a couple of pastel sundresses. Sizes S to M, mostly 4–8. All washed. Hangers included. Happy to let you look through them in the lobby.', 60, 'fashion', 'good', 'active', '[{"fileId":"6acf7bd3ead997d09a9d931f","path":"/stoop/seed/summer-dresses-1.jpg","width":960,"height":1440}]'::jsonb, 40.79, -73.9725, 'Upper West Side, Manhattan', now() - interval '14918 minutes', now() - interval '14918 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('3571a42c-0f14-5d60-8c18-8affb9a5dc55', '33f1a5e1-6e59-56f3-a505-ad73d1d3f1f1', '1960s portable TV on tapered legs', 'Black and white portable set with silver trim on its original tapered metal stand. It powers on and hums, but you''d need a converter box and probably a repair to get a picture. Mostly a decor piece now, and a good one. About 3 feet tall on the legs. The doorman can help you load it.', 75, 'electronics', 'fair', 'active', '[{"fileId":"6acf7bd4ead997d09a9d958f","path":"/stoop/seed/vintage-tv-1.jpg","width":960,"height":641}]'::jsonb, 40.785, -73.98, 'Upper West Side, Manhattan', now() - interval '24850 minutes', now() - interval '24850 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('fdb18e07-0e1c-54e2-8f42-b98a0c42dda2', '33f1a5e1-6e59-56f3-a505-ad73d1d3f1f1', 'Lot of old hand tools: hatchet, hammers, ice tongs and more', 'My late husband''s tools from the country house: hatchet with leather sheath, claw hammer, ball-peen hammer, Craftsman steel tape, ice tongs, a hay hook, two pocket knives, a flashlight, an oil can and work gloves. Patina and rust as you''d expect, handles are solid. I''d love them to go to someone who''ll use them. Sold as a lot.', 65, 'misc', 'fair', 'active', '[{"fileId":"6acf7bd4ead997d09a9d9689","path":"/stoop/seed/old-hand-tools-1.jpg","width":960,"height":780}]'::jsonb, 40.7875, -73.97, 'Upper West Side, Manhattan', now() - interval '9158 minutes', now() - interval '9158 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('820b12ac-1049-5d0a-a656-43b41f5a7326', '33f1a5e1-6e59-56f3-a505-ad73d1d3f1f1', 'Daniel Wellington Classic watch, rose gold, 36mm', 'Classic DW with a white dial, rose gold case and dark brown leather strap. A gift from my grandchildren that I never got used to wearing, I''m a Timex person. New battery, a few marks on the strap keeper. Original box.', 50, 'fashion', 'good', 'active', '[{"fileId":"6acf7bd4ead997d09a9d9764","path":"/stoop/seed/dw-watch-1.jpg","width":960,"height":641}]'::jsonb, 40.7825, -73.9725, 'Upper West Side, Manhattan', now() - interval '29096 minutes', now() - interval '29096 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('cbf77355-e0c4-5627-97ee-dc48002171ea', '0be9de42-1932-5e69-812b-f328df1147b3', 'About 8 lb of loose LEGO, mixed colors', 'Big bin of mixed LEGO bricks, plates, technic beams, wheels and a few windows. Roughly 8 pounds, all genuine LEGO, no instructions or complete sets. Washed in a mesh bag before listing. The kids have moved on to video games, so we''re reclaiming the closet.', 70, 'kids', 'good', 'active', '[{"fileId":"6acf7bd4ead997d09a9d987f","path":"/stoop/seed/lego-bulk-1.webp","width":1024,"height":684}]'::jsonb, 40.67, -73.9425, 'Crown Heights, Brooklyn', now() - interval '1773 minutes', now() - interval '1773 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('87b3fdd5-31f6-5edf-87bc-a7142178ee70', '0be9de42-1932-5e69-812b-f328df1147b3', 'Three strollers: two umbrella and one full-size', 'Black umbrella stroller, a red umbrella stroller with a padded liner, and a full-size grey stroller with a big basket. All fold, all brakes work, wheels roll straight. $100 for all three or $40 each. Bags and blanket not included. Holding them for a family from church until Friday.', 100, 'kids', 'good', 'reserved', '[{"fileId":"6acf7bd5ead997d09a9d9a76","path":"/stoop/seed/stroller-trio-1.webp","width":1024,"height":683}]'::jsonb, 40.66, -73.95, 'Prospect Lefferts Gardens, Brooklyn', now() - interval '7681 minutes', now() - interval '7681 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('3bbbf8d9-8139-55be-8a70-bb5c6bb1c150', '0be9de42-1932-5e69-812b-f328df1147b3', 'Free: shelf of kids'' paperbacks, about 40 books', 'Picture books and early readers: Dr. Seuss, Fireman Sam, science experiment books and a bunch of South African readers from my wife''s family. Some covers are worn but every page is there. Take the whole stack. I''ll put them in a box on our stoop on Park Place.', 0, 'kids', 'good', 'active', '[{"fileId":"6acf7bd5ead997d09a9d9b9a","path":"/stoop/seed/free-kids-books-1.jpg","width":960,"height":640}]'::jsonb, 40.6725, -73.9375, 'Crown Heights, Brooklyn', now() - interval '555 minutes', now() - interval '555 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('bd223a42-4f2a-5037-b9f1-ebd14fe48200', '0be9de42-1932-5e69-812b-f328df1147b3', '2013 Volkswagen Beetle, pale yellow, 68k miles', '2013 Beetle 2.5L automatic in pale yellow, 68,000 miles. Clean Carfax, two owners, all service at the VW dealer in Brooklyn. New front brakes and battery this year. Small door ding on the passenger side. We bought a minivan when baby number two arrived. Parked at my brother''s in Ditmas Park, test drives on weekends.', 8900, 'vehicles', 'good', 'active', '[{"fileId":"6acf7bd5ead997d09a9d9ce4","path":"/stoop/seed/yellow-beetle-1.jpg","width":960,"height":640}]'::jsonb, 40.64, -73.9625, 'Ditmas Park, Brooklyn', now() - interval '3361 minutes', now() - interval '3361 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('2b3dc85b-0297-54ba-83ba-92ea884c3739', '0be9de42-1932-5e69-812b-f328df1147b3', 'Drive-up storage unit sublet, Red Hook — $160/mo', 'Ground-floor 5x10 drive-up unit at a storage place in Red Hook, roll-up door, 24-hour access with a code. I prepaid through March and we no longer need it. You take over at $160/month, cheaper than the walk-in rate. Fits a studio''s worth of boxes or a couple of bikes.', 160, 'property', null, 'active', '[{"fileId":"6acf7bd6ead997d09a9d9e35","path":"/stoop/seed/red-hook-storage-1.jpg","width":960,"height":640}]'::jsonb, 40.675, -74.01, 'Red Hook, Brooklyn', now() - interval '17872 minutes', now() - interval '17872 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('09630afc-0ce7-5f7d-947e-daf722dcd98d', '0be9de42-1932-5e69-812b-f328df1147b3', 'Large glass hamster habitat with wheel, house and ladder', 'Long glass habitat, about 40" x 20", with a ventilated wooden mesh lid, wooden wheel, two-story house, ladder and a hideout. Way better than the plastic cages. Our hamster lived a long happy life in it. Cleaned out, bedding not included. The bookcase stand isn''t included either. Bring two people.', 70, 'pets', 'good', 'active', '[{"fileId":"6acf7bd6ead997d09a9d9fa6","path":"/stoop/seed/hamster-habitat-1.jpg","width":1024,"height":781},{"fileId":"6acf9d6fead997d09a62a4fe","path":"/stoop/seed/hamster-habitat-118e4b6a.jpg","width":1024,"height":754}]'::jsonb, 40.6675, -73.94, 'Crown Heights, Brooklyn', now() - interval '22155 minutes', now() - interval '22155 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('3312cd9b-831e-537a-82f4-a0e41ed25fab', '0be9de42-1932-5e69-812b-f328df1147b3', 'Kids'' quad roller skates, two pairs (youth 3 and 5)', 'One red pair (youth 3) and one black Roller Derby Firestar pair (youth 5). Wheels and bearings roll smoothly, toe stops have plenty of life, laces and velcro straps intact. Our two learned on these at the Prospect Park rink. $35 for both or $20 each.', 35, 'sports', 'good', 'active', '[{"fileId":"6acf7bd6ead997d09a9da142","path":"/stoop/seed/quad-skates-1.jpg","width":1024,"height":768}]'::jsonb, 40.67, -73.9375, 'Crown Heights, Brooklyn', now() - interval '6167 minutes', now() - interval '6167 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('72e0e0c9-274b-5e00-91f6-8f505a76ee0c', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Furnished loft sublet, Greenpoint, Nov–Apr — $3,600/mo', 'My loft is available while I''m in Berlin: November through April, possibly longer. About 900 sq ft in an old brick factory: exposed brick, timber beams, big windows and wide-plank pine floors. Open kitchen with a big island and a gas range, a sofa and two armchairs around the fireplace. The bedroom is a separate room off the kitchen, plus a sleeping loft up the stairs for guests, and the bathroom has a soaking tub. Fully furnished, utilities and wifi included. Ten minutes to the Greenpoint Ave G. Ideal for a quiet person or a couple who''ll water the plants.', 3600, 'property', null, 'active', '[{"fileId":"6acf9d6fead997d09a62a6eb","path":"/stoop/seed/greenpoint-loft-sublet-311563dd.webp","width":1024,"height":681},{"fileId":"6acf9d70ead997d09a62a837","path":"/stoop/seed/greenpoint-loft-sublet-8d2be019.webp","width":1024,"height":681},{"fileId":"6acf9d70ead997d09a62aa24","path":"/stoop/seed/greenpoint-loft-sublet-9f173d2d.webp","width":1024,"height":681},{"fileId":"6acf9d72ead997d09a62af46","path":"/stoop/seed/greenpoint-loft-sublet-8239a6e3.webp","width":1024,"height":681},{"fileId":"6acf9d73ead997d09a62b194","path":"/stoop/seed/greenpoint-loft-sublet-3c6230de.webp","width":1024,"height":681},{"fileId":"6acf9d74ead997d09a62b6a1","path":"/stoop/seed/greenpoint-loft-sublet-7b6da569.webp","width":1024,"height":681}]'::jsonb, 40.73, -73.955, 'Greenpoint, Brooklyn', now() - interval '1654 minutes', now() - interval '1654 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('7158d08b-2f46-57b4-95cb-c21711799d0b', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Cognac leather butterfly chair, black frame', 'Butterfly chair with a cognac leather sling on a black steel frame. The leather has softened and darkened nicely, no tears. Frame folds flat for transport. Throw and pillow not included. Was the best reading spot in my apartment.', 120, 'home', 'good', 'active', '[{"fileId":"6acf7bd7ead997d09a9da688","path":"/stoop/seed/butterfly-chair-1.jpg","width":960,"height":641}]'::jsonb, 40.7275, -73.95, 'Greenpoint, Brooklyn', now() - interval '3435 minutes', now() - interval '3435 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('30f97f2b-4a9d-598e-80dd-931e43b2ec3b', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Konica Auto S3 rangefinder, 38mm f/1.8', 'Compact rangefinder with the sharp Hexanon 38mm f/1.8. Shutter-priority auto exposure works with a modern battery adapter, which I include. Rangefinder patch is bright, glass is clean, light seals replaced. Shot a roll last month to test. Sold.', 180, 'hobbies', 'good', 'sold', '[{"fileId":"6acf7bd7ead997d09a9dae19","path":"/stoop/seed/konica-auto-s3-1.jpg","width":960,"height":640}]'::jsonb, 40.7325, -73.9525, 'Greenpoint, Brooklyn', now() - interval '26438 minutes', now() - interval '26438 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('e827615b-5ccb-5930-a48a-f3f627ad61f8', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Canon EF 24mm f/1.4L plus two vintage primes', 'Canon EF 24mm f/1.4L (first version) with both caps, plus two vintage manual lenses: a 50mm f/1.7 and a 28mm f/2.8 macro, which need adapters on modern bodies. The 24L autofocuses quickly and has no haze or fungus. $680 for all three, or $620 for the Canon alone and $40 each for the others.', 680, 'electronics', 'good', 'active', '[{"fileId":"6acf7bd7ead997d09a9db536","path":"/stoop/seed/lens-trio-1.jpg","width":960,"height":640}]'::jsonb, 40.73, -73.9525, 'Greenpoint, Brooklyn', now() - interval '4653 minutes', now() - interval '4653 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('5c24b410-c30d-5b87-8da4-e145497a25cf', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Brown leather weekender duffle with shoulder strap', 'Big distressed brown leather duffle with two front pockets, side buckles and a detachable shoulder strap. Fits three or four days of clothes and a camera. Zipper runs smoothly, canvas lining is clean. It''s too heavy to take on the plane, which is why it''s going. On hold until Thursday.', 110, 'fashion', 'good', 'reserved', '[{"fileId":"6acf7bd7ead997d09a9db802","path":"/stoop/seed/leather-duffle-1.jpg","width":960,"height":640}]'::jsonb, 40.7125, -73.9575, 'Williamsburg, Brooklyn', now() - interval '9158 minutes', now() - interval '9158 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('bcfc8c29-00ee-54a3-8c68-032b8bb8cc5b', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Gold aviator sunglasses, blue mirrored lenses, with case', 'Thin gold metal frames with polarized blue mirrored lenses and the round metal case. No scratches on the lenses, nose pads replaced. I can meet at Tompkins Square Park on Thursday, or in Greenpoint any evening.', 25, 'fashion', 'good', 'active', '[{"fileId":"6acf7bd8ead997d09a9db8bf","path":"/stoop/seed/blue-aviators-1.jpg","width":960,"height":640}]'::jsonb, 40.7275, -73.9825, 'East Village, Manhattan', now() - interval '12001 minutes', now() - interval '12001 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('4da53cc8-21bf-549b-9593-9c70900446fd', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Tan leather wingtip chukka boots, men''s 10', 'Cognac leather wingtip chukkas with brogue detailing, men''s US 10. Bought for a shoot and worn a few times since. Soles have plenty left, a little creasing at the toes. Tie and camera in the photo are not part of the sale.', 70, 'fashion', 'good', 'active', '[{"fileId":"6acf7bd8ead997d09a9db99a","path":"/stoop/seed/wingtip-boots-1.jpg","width":960,"height":640}]'::jsonb, 40.7275, -73.955, 'Greenpoint, Brooklyn', now() - interval '16321 minutes', now() - interval '16321 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('6fd8e9d4-7991-5eb4-92f6-393f382760f6', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Black step-through city bike with wicker basket', 'Upright step-through bike, black frame, blue tires, wicker front basket and a floral chain guard. Three-speed internal hub, coaster brake plus a front hand brake, front light. Perfect for grocery runs. Lock included. Moving to Berlin where I''ll finally have a real Dutch bike.', 280, 'vehicles', 'good', 'active', '[{"fileId":"6acf7bd8ead997d09a9dba85","path":"/stoop/seed/dutch-city-bike-1.jpg","width":960,"height":640}]'::jsonb, 40.7325, -73.955, 'Greenpoint, Brooklyn', now() - interval '1995 minutes', now() - interval '1995 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('af3b80fc-7358-5843-ae85-7047cf80f2bd', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Free: warm white LED string lights, about 5 strands', 'A tangle of warm white LED fairy lights, around 5 strands of 10m each, plug-in. They all work, they''re just very tangled. Used them as a backdrop in my studio. Free to whoever has the patience. Pickup near McGuinness.', 0, 'misc', 'good', 'active', '[{"fileId":"6acf7bd8ead997d09a9dbb63","path":"/stoop/seed/free-string-lights-1.jpg","width":960,"height":640}]'::jsonb, 40.73, -73.95, 'Greenpoint, Brooklyn', now() - interval '66 minutes', now() - interval '66 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.listings (id, seller_id, title, description, price, category, condition, status, images, lat, lng, location_name, created_at, updated_at, is_seed) values ('d61de4f7-a646-5f5b-9cc8-fd345e2d8669', '87a623ce-7619-503b-8a24-2e69bd4d0121', 'Orange corduroy bolster dog bed, medium', 'Orange corduroy bed with a raised bolster on three sides, about 30" x 24". Removable, washable cover, just washed. Our corgi Biscuit is staying with my parents in Jersey and they already bought her a new one. Corgi not included, she''s very sorry.', 25, 'pets', 'good', 'active', '[{"fileId":"6acf7bd9ead997d09a9dbd29","path":"/stoop/seed/orange-dog-bed-1.jpg","width":1023,"height":740},{"fileId":"6acf9d75ead997d09a62b8cf","path":"/stoop/seed/orange-dog-bed-fa870cb7.jpg","width":1024,"height":746}]'::jsonb, 40.7275, -73.9525, 'Greenpoint, Brooklyn', now() - interval '7718 minutes', now() - interval '7718 minutes', true) on conflict (id) do update set seller_id = excluded.seller_id, title = excluded.title, description = excluded.description, price = excluded.price, category = excluded.category, condition = excluded.condition, status = excluded.status, images = excluded.images, lat = excluded.lat, lng = excluded.lng, location_name = excluded.location_name, created_at = excluded.created_at, updated_at = excluded.updated_at, is_seed = true;
insert into public.conversations (id, listing_id, buyer_id, seller_id, created_at, is_seed) values ('6895208f-40a2-5616-b50b-c37c38e55040', 'ba34e1d3-435b-5f89-a092-b503ca76459e', '0be9de42-1932-5e69-812b-f328df1147b3', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', now() - interval '191 minutes', true);
insert into public.messages (conversation_id, sender_id, body, created_at) values ('6895208f-40a2-5616-b50b-c37c38e55040', '0be9de42-1932-5e69-812b-f328df1147b3', 'Hi Maya, is this still available?', now() - interval '190 minutes');
insert into public.messages (conversation_id, sender_id, body, created_at) values ('6895208f-40a2-5616-b50b-c37c38e55040', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Hi! Yes it is.', now() - interval '172 minutes');
insert into public.messages (conversation_id, sender_id, body, created_at) values ('6895208f-40a2-5616-b50b-c37c38e55040', '0be9de42-1932-5e69-812b-f328df1147b3', 'Great. Could I come by tomorrow after 6?', now() - interval '165 minutes');
insert into public.messages (conversation_id, sender_id, body, created_at) values ('6895208f-40a2-5616-b50b-c37c38e55040', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', '6:30 works. I''m near the Grand Army Plaza side of the park.', now() - interval '150 minutes');
insert into public.messages (conversation_id, sender_id, body, created_at) values ('6895208f-40a2-5616-b50b-c37c38e55040', '0be9de42-1932-5e69-812b-f328df1147b3', 'Perfect. Would you do a little less if I bring cash?', now() - interval '12 minutes');
insert into public.conversations (id, listing_id, buyer_id, seller_id, created_at, is_seed) values ('8c6e4df8-0530-5c7f-b207-bda246cace6d', '6a7bb20b-9dd0-5451-9630-37698a8bbd32', '33f1a5e1-6e59-56f3-a505-ad73d1d3f1f1', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', now() - interval '3001 minutes', true);
insert into public.messages (conversation_id, sender_id, body, created_at) values ('8c6e4df8-0530-5c7f-b207-bda246cace6d', '33f1a5e1-6e59-56f3-a505-ad73d1d3f1f1', 'Hello! Interested in this. Still around?', now() - interval '3000 minutes');
insert into public.messages (conversation_id, sender_id, body, created_at) values ('8c6e4df8-0530-5c7f-b207-bda246cace6d', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'It is. Happy to hold it for you until the weekend.', now() - interval '2950 minutes');
insert into public.messages (conversation_id, sender_id, body, created_at) values ('8c6e4df8-0530-5c7f-b207-bda246cace6d', '33f1a5e1-6e59-56f3-a505-ad73d1d3f1f1', 'That would be lovely, thank you. Saturday morning?', now() - interval '2900 minutes');
insert into public.messages (conversation_id, sender_id, body, created_at) values ('8c6e4df8-0530-5c7f-b207-bda246cace6d', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Saturday at 10 works. I''ll mark it on hold.', now() - interval '2880 minutes');
insert into public.conversations (id, listing_id, buyer_id, seller_id, created_at, is_seed) values ('6fb6ec03-b625-5c88-b67a-e12ede25c8c9', 'b44e7362-6600-519b-ba15-bf8f3e859d8a', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', '499a659a-d8f7-5f18-b366-9e13d33860e0', now() - interval '601 minutes', true);
insert into public.messages (conversation_id, sender_id, body, created_at) values ('6fb6ec03-b625-5c88-b67a-e12ede25c8c9', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', 'Hey, is this still for sale?', now() - interval '600 minutes');
insert into public.messages (conversation_id, sender_id, body, created_at) values ('6fb6ec03-b625-5c88-b67a-e12ede25c8c9', '499a659a-d8f7-5f18-b366-9e13d33860e0', 'Yep! Want to come take a look this week?', now() - interval '30 minutes');
insert into public.conversations (id, listing_id, buyer_id, seller_id, created_at, is_seed) values ('c745269d-8518-574d-b27a-fccb59e35c98', '2b0f8cee-7c31-525a-9a59-1b0708697e06', 'b2a0af7c-7ba8-5cfc-b395-ab8d1fd58c06', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', now() - interval '5001 minutes', true);
