insert into public.messages (conversation_id, sender_id, body, created_at) values ('c745269d-8518-574d-b27a-fccb59e35c98', '807ab3c3-76f9-52c5-997b-cc8bfacbbe96', 'Everything you see, yes.', now() - interval '4900 minutes');
